const $=id=>document.getElementById(id),canvas=$('scene'),ctx=canvas.getContext('2d'),backdrop=new Image();backdrop.src='nebula-v1.png';let game=null,paused=true,demo=false,shown=null,frame=performance.now(),elapsed=0,botAt=0,botQ=null,botCount=0,w=400,h=500,phase=0,shipX=.5,shipTarget=.5,bolts=[],sparks=[],shock=0,bannerTimer=0,ended=false,wallet=0;try{const v=Number(localStorage.getItem('starDefenderCoins.v1'));wallet=Number.isSafeInteger(v)&&v>=0?v:0}catch{}const stars=Array.from({length:65},()=>({x:Math.random(),y:Math.random(),r:.5+Math.random()*1.3}));const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
