function start(isDemo=false){numberEntry?.reset?.();beginPractice(isDemo);arcadeSession=Date.now().toString(36)+Math.random().toString(36).slice(2);arcadeRewardNo=0;arcadePost({type:'arcade-mode',mode:isDemo?'demo':'play'});round?.start(isDemo);game=new DefenderEngine.Game({timed:!!round?.enabled,operation:$('operation').value,range:Number($('range').value)});demo=isDemo;paused=practiceStopped;numberEntry?.setPaused?.(paused);showPracticeQuestion();shown=null;elapsed=0;botAt=0;botQ=null;botCount=0;ended=false;shipX=shipTarget=.5;bolts=[];sparks=[];frame=performance.now();$('setup').close();$('end').close();$('feedback').textContent='Type the answer to fire. Build a four-answer laser combo!';events();choices();ui()}
function ship(x,y,size,color,enemy=false,boss=false){ctx.save();ctx.translate(x,y);if(enemy)ctx.rotate(Math.PI);ctx.shadowColor=color;ctx.shadowBlur=boss?16:8;const g=ctx.createLinearGradient(0,-size,0,size);g.addColorStop(0,'#effaff');g.addColorStop(.4,color);g.addColorStop(1,'#173454');ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(0,-size);ctx.lineTo(size*.32,-size*.25);ctx.lineTo(size*.9,size*.35);ctx.lineTo(size*.85,size*.62);ctx.lineTo(size*.2,size*.37);ctx.lineTo(0,size*.61);ctx.lineTo(-size*.2,size*.37);ctx.lineTo(-size*.85,size*.62);ctx.lineTo(-size*.9,size*.35);ctx.lineTo(-size*.32,-size*.25);ctx.closePath();ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#f0ffff55';ctx.lineWidth=.8;ctx.stroke();ctx.fillStyle='#041222';ctx.beginPath();ctx.ellipse(0,-size*.13,size*.15,size*.25,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=enemy?'#ffe37a':'#70faff';ctx.beginPath();ctx.ellipse(-size*.03,-size*.18,size*.08,size*.13,0,0,Math.PI*2);ctx.fill();if(!enemy){ctx.shadowColor='#59d9ff';ctx.shadowBlur=16;ctx.fillStyle='#93ecff';ctx.beginPath();ctx.moveTo(-size*.14,size*.43);ctx.lineTo(0,size*(.9+(Math.sin(phase*20)+1)*.15));ctx.lineTo(size*.14,size*.43);ctx.fill()}if(boss){ctx.fillStyle='#ffcb79';ctx.fillRect(-size*.6,size*.2,size*1.2,size*.07)}ctx.restore()}
function draw(dt){phase+=paused?0:dt;ctx.clearRect(0,0,w,h);ctx.fillStyle='#080c23';ctx.fillRect(0,0,w,h);if(backdrop.complete&&backdrop.naturalWidth){const scale=Math.max(w/backdrop.naturalWidth,h/backdrop.naturalHeight),dw=backdrop.naturalWidth*scale,dh=backdrop.naturalHeight*scale;ctx.globalAlpha=.72;ctx.drawImage(backdrop,(w-dw)/2,(h-dh)/2,dw,dh);ctx.globalAlpha=1}for(const s of stars){ctx.globalAlpha=.4+.35*Math.sin(phase+s.x*10);ctx.fillStyle='#ceeaff';ctx.beginPath();ctx.arc(s.x*w,((s.y+phase*.007)%1)*h,s.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;const base=.89*h;ctx.strokeStyle='#62dfff66';ctx.setLineDash([5,9]);ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(8,base);ctx.lineTo(w-8,base);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#8eb2d7';ctx.font='8px system-ui';ctx.fillText('SHIELD LINE',12,base-7);if(game){for(const a of game.aliens){const x=(a.x+Math.sin(phase*.6)*.03)*w,y=a.y*h,size=a.boss?Math.min(w*.105,40):Math.min(w*.055,23);ship(x,y,size,a.boss?'#ffa875':a.row===0?'#bda1ff':a.row===1?'#6ce9bb':'#6fcfff',true,a.boss);if(a.boss){ctx.fillStyle='#ffcb7955';ctx.fillRect(x-size,y-size-10,size*2,3);ctx.fillStyle='#ffd18c';ctx.fillRect(x-size,y-size-10,size*2*(a.hp/3),3)}}}if(!paused)shipX+=(shipTarget-shipX)*(1-Math.exp(-dt*5));ship(shipX*w,h*.96,Math.min(w*.085,32),'#6adbf4');for(const b of bolts){const flight=game?.shots.find(s=>s.id===b.id);if(flight&&!b.hit)b.t=Math.max(0,Math.min(1,1-flight.left/.28));if(b.hit&&!paused)b.impactLife-=dt;const target=game?.aliens.find(a=>a.id===b.id);if(target&&!b.hit){b.tx=target.x+Math.sin(phase*.6)*.03;b.ty=target.y}const t=Math.min(b.hit?1:.99,b.t),x=(b.x+(b.tx-b.x)*t)*w,y=(b.y+(b.ty-b.y)*t)*h;ctx.strokeStyle=b.beam?'#baa0ff':'#a4faff';ctx.shadowColor=ctx.strokeStyle;ctx.shadowBlur=b.beam?22:9;ctx.lineWidth=b.beam?8:3;ctx.beginPath();ctx.moveTo(x,y+Math.min(40,h*.08));ctx.lineTo(x,y);ctx.stroke();ctx.shadowBlur=0;if(b.hit&&!b.burst){b.burst=true;for(let i=0;i<(reduced?4:15);i++){const angle=Math.random()*Math.PI*2;sparks.push({x:b.tx*w,y:b.ty*h,vx:Math.cos(angle)*(25+Math.random()*90),vy:Math.sin(angle)*(25+Math.random()*90),life:.7,color:b.beam?'#c4a0ff':'#8df5fc'})}}}bolts=bolts.filter(b=>!b.hit||b.impactLife>0);for(const p of sparks){if(!paused){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt}ctx.globalAlpha=p.life/.7;ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,3,3)}sparks=sparks.filter(p=>p.life>0).slice(-100);ctx.globalAlpha=1;if(shock>0){ctx.fillStyle='rgba(255,110,97,'+shock*.25+')';ctx.fillRect(0,0,w,h);if(!paused)shock=Math.max(0,shock-dt*2)}if(paused&&game?.running){ctx.fillStyle='#050d22aa';ctx.fillRect(0,0,w,h);ctx.fillStyle='#d7edff';ctx.font='900 24px system-ui';ctx.textAlign='center';ctx.fillText('PAUSED',w/2,h/2);ctx.textAlign='left'}}
// Demo bots and deadlines advance together, even after a slow or delayed first frame.
function advanceDemo(rawDt){let left=Math.min(1,Math.max(0,rawDt));while(left>1e-9&&game?.running&&!paused){const step=Math.min(.025,left);left-=step;if(botQ!==game.question){botQ=game.question;botCount++;botAt=elapsed;}elapsed+=step;game.update(step);events();choices();if(botQ!==game.question){botQ=game.question;botCount++;botAt=elapsed;}if(game.running&&game.cooldown===0&&game.questionElapsed+1e-9>=(elapsed<40?.8:2.8))answer(botCount%5===0?ArcadeNumberEntry.wrong(game.question.answer):game.question.answer);}}
function loop(now){if(practiceStopped){paused=true;numberEntry?.setPaused?.(true);}const dt=Math.max(0,(now-frame)/1000);frame=now;if(game&&!paused){const simulationDt=demo?Math.min(dt,1):dt;if(round?.tick(simulationDt,true)){game.running=false;game.events.push({type:'over'});}else if(!document.hidden){if(demo)advanceDemo(simulationDt);else{elapsed+=dt;game.update(dt);}}events();choices();bannerTimer-=dt;if(bannerTimer<=0)$('banner').textContent=''}ui();draw(Math.min(dt,.05));requestAnimationFrame(loop)}
