window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==parent)return;if(e.data?.type==='arcade-wallet'&&Number.isFinite(e.data.coins)){wallet=e.data.coins;ui()}if(e.data?.type==='arcade-pause'){if(game?.running&&!paused){paused=true;numberEntry?.setPaused?.(true);ui()}return}if(e.data?.type!=='arcade-command')return;if(e.data.action==='demo')start(true);else if(e.data.action==='play'){paused=true;numberEntry?.setPaused?.(true);ui();$('resume').hidden=!game?.running;if($('end').open)$('end').close();if(!$('setup').open)$('setup').showModal()}});
